create or replace function catalog.search_sellable_products(
  p_tenant_id uuid,
  p_store_id uuid,
  p_keyword text,
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path = catalog, iam, extensions, pg_temp
as $$
declare
  v_keyword text := nullif(
    lower(btrim(catalog.unaccent_immutable(coalesce(p_keyword, '')))),
    ''
  );
  v_sku text := catalog._normalize_product_sku(p_keyword);
  v_barcode text := catalog._normalize_product_barcode(p_keyword);
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from iam.memberships membership
    where membership.tenant_id = p_tenant_id
      and membership.user_id = auth.uid()
  ) then
    raise exception 'tenant access denied';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  if not exists (
    select 1
    from iam.membership_store_scopes scope
    join iam.stores store
      on store.id = scope.store_id
     and store.tenant_id = scope.tenant_id
    where scope.tenant_id = p_tenant_id
      and scope.user_id = auth.uid()
      and scope.store_id = p_store_id
      and store.tenant_id = p_tenant_id
      and store.status = 'active'
  ) then
    raise exception 'store access denied';
  end if;

  return (
    with matched_products as (
      select
        p.id,
        p.tenant_id,
        p.name,
        p.trade_name,
        p.sku,
        p.barcode,
        p.is_ready_to_sell
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.business_status = 'active'::catalog.product_business_status
        and p.is_ready_to_sell = true
        and (
          v_keyword is null
          or p.id::text = btrim(p_keyword)
          or p.search_text like '%' || v_keyword || '%'
          or p.sku = v_sku
          or p.barcode = v_barcode
        )
      order by p.name asc, p.id asc
      limit least(greatest(coalesce(p_limit, 50), 1), 100)
      offset greatest(coalesce(p_offset, 0), 0)
    )
    select jsonb_build_object(
      'items', coalesce(
        jsonb_agg(
          jsonb_build_object(
            'product_id', p.id,
            'sku', p.sku,
            'display_name', p.name,
            'trade_name', p.trade_name,
            'is_sellable', p.is_ready_to_sell,
            'block_reason', null,
            'currency_code', product_price.currency,
            'list_price_minor', product_price.list_price_minor,
            'floor_price_minor', product_price.floor_price_minor,
            'available_stock_micros', (
              select case
                when sp.basic_stock_quantity_base is null then null
                else (trunc(sp.basic_stock_quantity_base) * 1000000)::bigint
              end
              from catalog.product_stock_profiles sp
              where sp.product_id = p.id
                and sp.tenant_id = p.tenant_id
              limit 1
            ),
            'units', units.units
          )
          order by p.name asc, p.id asc
        ),
        '[]'::jsonb
      )
    )
    from matched_products p
    join lateral (
      select bp.currency,
        pb.list_price_after_vat::bigint as list_price_minor,
        pb.floor_price_after_vat::bigint as floor_price_minor
      from catalog.product_units pu
      join catalog.product_base_price_profiles bp
        on bp.product_id = p.id
       and bp.tenant_id = p.tenant_id
      join catalog.product_unit_price_bands pb
        on pb.product_id = p.id
       and pb.product_unit_id = pu.id
       and pb.tenant_id = p.tenant_id
       and pb.status = 'active'
       and pb.effective_from <= now()
       and (pb.effective_to is null or pb.effective_to > now())
      where pu.tenant_id = p_tenant_id
        and pu.product_id = p.id
        and pu.is_active = true
        and pb.list_price_after_vat is not null
        and trunc(pb.list_price_after_vat) = pb.list_price_after_vat
        and (pb.floor_price_after_vat is null
          or trunc(pb.floor_price_after_vat) = pb.floor_price_after_vat)
      order by pu.is_base_unit desc, pu.unit_name asc, pu.id asc
      limit 1
    ) product_price on true
    join lateral (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'product_unit_id', pu.id,
            'unit_code', pu.unit_name,
            'unit_name', pu.unit_name,
            'barcode', p.barcode,
            'is_default', pu.is_base_unit,
            'is_active', pu.is_active,
            'is_sellable', p.is_ready_to_sell and pu.is_active,
            'block_reason', null,
            'list_price_minor', pb.list_price_after_vat::bigint,
            'floor_price_minor', pb.floor_price_after_vat::bigint,
            'available_stock_micros', case
              when sp.basic_stock_quantity_base is null then null
              when coalesce(pu.conversion_rate_to_base, 0) <= 0 then null
              else (
                trunc(sp.basic_stock_quantity_base / pu.conversion_rate_to_base)
                * 1000000
              )::bigint
            end
          )
          order by pu.is_base_unit desc, pu.unit_name asc, pu.id asc
        ),
        '[]'::jsonb
      ) as units
      from catalog.product_units pu
      join catalog.product_unit_price_bands pb
        on pb.product_id = p.id
       and pb.product_unit_id = pu.id
       and pb.tenant_id = p.tenant_id
       and pb.status = 'active'
       and pb.effective_from <= now()
       and (pb.effective_to is null or pb.effective_to > now())
      left join catalog.product_stock_profiles sp
        on sp.product_id = p.id
       and sp.tenant_id = p.tenant_id
      where pu.tenant_id = p_tenant_id
        and pu.product_id = p.id
        and pu.is_active = true
        and pb.list_price_after_vat is not null
        and trunc(pb.list_price_after_vat) = pb.list_price_after_vat
        and (pb.floor_price_after_vat is null
          or trunc(pb.floor_price_after_vat) = pb.floor_price_after_vat)
    ) units on true
  );
end;
$$;

