create or replace function catalog.list_sellable_product_units(
  p_tenant_id uuid,
  p_store_id uuid,
  p_product_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = catalog, iam, pg_temp
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from iam.memberships membership
    where membership.tenant_id = p_tenant_id
      and membership.user_id = auth.uid()
  ) then
    raise exception 'tenant access denied';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  if not exists (
    select 1
    from iam.membership_store_scopes scope
    join iam.stores store
      on store.id = scope.store_id
     and store.tenant_id = scope.tenant_id
    where scope.tenant_id = p_tenant_id
      and scope.user_id = auth.uid()
      and scope.store_id = p_store_id
      and store.tenant_id = p_tenant_id
      and store.status = 'active'
  ) then
    raise exception 'store access denied';
  end if;

  return (
    select jsonb_build_object(
      'units', coalesce(
        jsonb_agg(
          jsonb_build_object(
            'product_unit_id', pu.id,
            'unit_code', pu.unit_name,
            'unit_name', pu.unit_name,
            'barcode', p.barcode,
            'is_default', pu.is_base_unit,
            'is_active', pu.is_active,
            'is_sellable', p.is_ready_to_sell and pu.is_active,
            'block_reason', null,
            'list_price_minor', pb.list_price_after_vat::bigint,
            'floor_price_minor', pb.floor_price_after_vat::bigint,
            'available_stock_micros', case
              when sp.basic_stock_quantity_base is null then null
              when coalesce(pu.conversion_rate_to_base, 0) <= 0 then null
              else (
                trunc(sp.basic_stock_quantity_base / pu.conversion_rate_to_base)
                * 1000000
              )::bigint
            end
          )
          order by pu.is_base_unit desc, pu.unit_name asc, pu.id asc
        ),
        '[]'::jsonb
      )
    )
    from catalog.products p
    join catalog.product_units pu
      on pu.product_id = p_product_id
     and pu.tenant_id = p_tenant_id
    join catalog.product_unit_price_bands pb
      on pb.product_id = p.id
     and pb.product_unit_id = pu.id
     and pb.tenant_id = p.tenant_id
     and pb.status = 'active'
     and pb.effective_from <= now()
     and (pb.effective_to is null or pb.effective_to > now())
    left join catalog.product_stock_profiles sp
      on sp.product_id = p.id
     and sp.tenant_id = p.tenant_id
    where p.id = p_product_id
      and p.tenant_id = p_tenant_id
      and p.business_status = 'active'::catalog.product_business_status
      and p.is_ready_to_sell = true
      and pu.is_active = true
      and pb.list_price_after_vat is not null
      and trunc(pb.list_price_after_vat) = pb.list_price_after_vat
      and (pb.floor_price_after_vat is null
        or trunc(pb.floor_price_after_vat) = pb.floor_price_after_vat)
  );
end;
$$;

